int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dario_wins = 0;
    int xerxes_wins = 0;

    for (int i = 0; i < n; i++) {
        int d, x;
        scanf("%d %d", &d, &x);
        if (x == (d + 1) % 5 || x == (d + 2) % 5) {
            dario_wins++;
        } else {
